import React, {useMemo} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import {cn} from "@/lib/utils";
import {useFormContext} from "@/cards/form/form.context";
import type {PiFieldProps} from "./field.types";

export const FieldCardComponent = (
  props: PiCardProps<PiFieldProps>,
): React.ReactNode => {
  const {
    label,
    fieldCard,
    name,
    description,
    error: propError,
    className,
    cardName,
  } = props;

  // When name is provided and we're inside a pi/form, use the form error.
  const form = useFormContext();
  const error = form.isInForm && name ? form.errors[name] : propError;

  // Stable id that links <FieldLabel htmlFor> to the inner control's id.
  const fieldId = React.useId();

  // Memoize the extra props forwarded to the inner card so that Pihanga does
  // not see a brand-new object on every render (which would cause it to treat
  // the inner card as a new/changed card and unmount/remount it).
  const isInvalid = Boolean(error);
  /*
      Pihanga's Card forwards every prop other than cardName / parentCard to
      the bound component.  We inject `id` (so the control's element gets
      the id that FieldLabel points at) and `invalid` (so the control can
      set aria-invalid without needing its own error/label logic).
    */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const fieldCardProps = useMemo<any>(
    () => ({
      cardName: fieldCard,
      parentCard: cardName,
      id: fieldId,
      invalid: isInvalid,
    }),
    [cardName, fieldCard, fieldId, isInvalid],
  );

  return (
    <Field
      data-invalid={Boolean(error) || undefined}
      className={cn(className)}
      data-pihanga={cardName}
    >
      <FieldLabel htmlFor={fieldId}>{label}</FieldLabel>

      <Card {...fieldCardProps} />

      {description && <FieldDescription>{description}</FieldDescription>}
      <FieldError>{error}</FieldError>
    </Field>
  );
};

import {createCardDeclaration, type PiCardRef} from "@pihanga2/core";

export const PI_FIELD_CARD = "pi/field";

export const Field = createCardDeclaration<PiFieldProps>(PI_FIELD_CARD);

export type PiFieldProps = {
  /** Visible label rendered above the control. */
  label: string;

  /**
   * The Pihanga card reference for the plain control to render
   * (e.g. pi/text-field, pi/select, pi/checkbox, …).
   *
   * The field card will forward an `id` prop and an `invalid` boolean to the
   * inner card via Pihanga's standard prop-passing mechanism so the control
   * can wire up accessibility attributes without needing its own label logic.
   */
  fieldCard: PiCardRef;

  /**
   * Field name — when provided the card reads the current error from
   * FormContext (when inside a pi/form) to decide whether to show an error.
   */
  name?: string;

  /** Secondary help text rendered below the control. */
  description?: string;

  /**
   * Static error message.  Overridden by the form-context error when `name`
   * is provided and the card is inside a pi/form.
   */
  error?: string;

  /** Additional CSS classes applied to the outer Field wrapper. */
  className?: string;
};

import {registerCardComponent} from "@pihanga2/core";

import {FieldCardComponent} from "./field.component";
import {PI_FIELD_CARD} from "./field.types";

export * from "./field.types";

// pi/field has no events of its own; events fire from the inner fieldCard.
registerCardComponent({
  name: PI_FIELD_CARD,
  component: FieldCardComponent,
});
